{
  "root": "main_stack",
  "state": {
    "mealPlan": [
      {
        "day": "Day 1",
        "breakfast": "Tofu Scramble with Spinach & Mushrooms: Crumbled tofu sautéed with spinach, sliced mushrooms, and a pinch of turmeric for color.",
        "lunch": "Large Mixed Green Salad with Hard-Boiled Eggs & Chickpeas: Mixed greens, 2 hard-boiled eggs, 1/4 cup chickpeas, cucumber, bell peppers, and a simple olive oil & vinegar dressing.",
        "dinner": "Tofu & Broccoli Stir-fry: Tofu cubes stir-fried with broccoli florets, bell peppers, and a low-sodium soy sauce/ginger/garlic sauce. Served with a small portion of cauliflower rice."
      },
      {
        "day": "Day 2",
        "breakfast": "Greek Yogurt with Berries & Chia Seeds: 1 cup plain Greek yogurt, 1/2 cup mixed berries, 1 tbsp chia seeds.",
        "lunch": "Leftover Tofu & Broccoli Stir-fry.",
        "dinner": "Lentil Soup: Hearty lentil soup with carrots, celery, and spinach. (Prepare a larger batch for multiple servings)."
      },
      {
        "day": "Day 3",
        "breakfast": "Spinach & Feta Omelette: 2-egg omelette with fresh spinach and a sprinkle of feta cheese.",
        "lunch": "Large Mixed Green Salad with Lentils & Avocado: Mixed greens, 1/2 cup cooked lentils, 1/4 avocado, cherry tomatoes, and a lemon-tahini dressing.",
        "dinner": "Tempeh & Asparagus Skewers: Marinated tempeh cubes and asparagus grilled or baked. Served with a side of steamed green beans."
      },
      {
        "day": "Day 4",
        "breakfast": "Protein Smoothie: Unsweetened almond milk, 1 scoop vegetarian protein powder, 1/2 banana (optional, for sweetness), spinach, and 1 tbsp almond butter.",
        "lunch": "Leftover Lentil Soup.",
        "dinner": "Eggplant & Chickpea Curry: Eggplant, chickpeas, and diced tomatoes simmered in a light coconut milk curry sauce. Served with a small side of sautéed kale."
      },
      {
        "day": "Day 5",
        "breakfast": "Cottage Cheese with Sliced Tomatoes & Black Pepper: 1 cup cottage cheese with fresh tomato slices and a dash of black pepper.",
        "lunch": "Large Mixed Green Salad with Tempeh & Bell Peppers: Mixed greens, sliced tempeh, colorful bell peppers, and a balsamic vinaigrette.",
        "dinner": "Black Bean Burgers (bun-less) with Side Salad: Homemade or store-bought vegetarian black bean patty served on a bed of lettuce with tomato and onion, alongside a simple side salad."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title",
        "intro_text",
        "daily_schedule_heading",
        "meal_plan_table",
        "tips_heading",
        "tips_intro_text",
        "tips_stack",
        "actions_heading",
        "actions_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "5-Day High-Protein, Low-Carb Vegetarian Meal Plan",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This meal plan offers a variety of high-protein, low-carb vegetarian options designed to be budget-friendly for one person, aiming for approximately $10 per day on groceries. It focuses on affordable staples like eggs, tofu, tempeh, lentils, and a wide array of non-starchy vegetables."
      },
      "children": []
    },
    "daily_schedule_heading": {
      "type": "Text",
      "props": {
        "text": "Your Daily Meal Schedule",
        "variant": "h2"
      },
      "children": []
    },
    "meal_plan_table": {
      "type": "Table",
      "props": {
        "statePath": "/mealPlan",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "day",
        "highlightColumns": [
          "breakfast",
          "lunch",
          "dinner"
        ],
        "columns": [
          {
            "key": "day",
            "label": "Day"
          },
          {
            "key": "breakfast",
            "label": "Breakfast"
          },
          {
            "key": "lunch",
            "label": "Lunch"
          },
          {
            "key": "dinner",
            "label": "Dinner"
          }
        ]
      },
      "children": []
    },
    "tips_heading": {
      "type": "Text",
      "props": {
        "text": "Tips for Success",
        "variant": "h2"
      },
      "children": []
    },
    "tips_intro_text": {
      "type": "Text",
      "props": {
        "text": "Maximize your meal plan with these helpful tips:"
      },
      "children": []
    },
    "tips_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "tip1",
        "tip2",
        "tip3",
        "tip4",
        "tip5"
      ]
    },
    "tip1": {
      "type": "Text",
      "props": {
        "text": "Meal Prep: Dedicate a few hours on a weekend to chop vegetables, cook grains, and prepare dressings. This saves significant time during the week."
      },
      "children": []
    },
    "tip2": {
      "type": "Text",
      "props": {
        "text": "Flexibility: Feel free to swap meals between days based on your preferences or what ingredients you have on hand. The goal is consistency, not rigid adherence."
      },
      "children": []
    },
    "tip3": {
      "type": "Text",
      "props": {
        "text": "Hydration: Drink plenty of water throughout the day. Herbal teas and black coffee are also good options."
      },
      "children": []
    },
    "tip4": {
      "type": "Text",
      "props": {
        "text": "Snacks: If you get hungry between meals, opt for low-carb, high-protein snacks like a handful of almonds, a hard-boiled egg, or a few slices of cucumber with hummus."
      },
      "children": []
    },
    "tip5": {
      "type": "Text",
      "props": {
        "text": "Seasoning: Don't be afraid to experiment with herbs and spices to keep your meals flavorful and exciting. Nutritional yeast can add a cheesy flavor to savory dishes."
      },
      "children": []
    },
    "actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "explore_recipes_button",
        "grocery_list_button",
        "keto_basics_button"
      ]
    },
    "explore_recipes_button": {
      "type": "Button",
      "props": {
        "label": "Explore More Vegetarian Recipes"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.example.com/vegetarian-recipes"
          }
        }
      }
    },
    "grocery_list_button": {
      "type": "Button",
      "props": {
        "label": "Generate Grocery List"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.example.com/grocery-list-generator"
          }
        }
      }
    },
    "keto_basics_button": {
      "type": "Button",
      "props": {
        "label": "Learn About Keto & Low-Carb Diets"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.example.com/keto-basics"
          }
        }
      }
    }
  }
}
